function recalc(){const w=equipped('weapon'),a=equipped('armor'),r=equipped('ring');const at=prog.attributes||defaults.attributes;player.maxHp=100+(prog.level-1)*12+(a?.hp||0)+at.vitality*14;player.maxMp=100+(prog.level-1)*5+at.arcane*7;player.damage=24+(prog.level-1)*4+(w?.attack||0)+(r?.attack||0)+(prog.forge||0)*3+at.strength*3;player.defense=(a?.defense||0)+(r?.defense||0)+at.vitality*.8;player.maxStamina=100+at.agility*4;player.stamina=Math.min(player.stamina||player.maxStamina,player.maxStamina);player.crit=.05+(w?.crit||0)+(r?.crit||0)+at.agility*.008;player.speed=240+at.agility*3;const storyChoice=prog.story?.choice||'';if(storyChoice==='DESAFIAR')player.damage*=1.05;if(storyChoice==='INVESTIGAR')player.crit+=.02;if(storyChoice==='ACEITAR O PODER')player.maxMp+=15;player.hp=Math.min(player.hp||player.maxHp,player.maxHp);player.mp=Math.min(player.mp||player.maxMp,player.maxMp)}
