function extractShadow(c){if(!c||c.used||state!=='dungeon')return;c.used=true;const chance=c.boss?.10:(c.elite?.72:.42);if(Math.random()>chance){ring(c.x,c.y,'#6b4b86',70,.35);particle(c.x,c.y,'#4f335f',10);notify(c.boss?'A SOMBRA DO CHEFE REJEITOU O VÍNCULO':'EXTRAÇÃO FALHOU — A SOMBRA SE DESFEZ',1200);return}const existing=prog.echoes.find(x=>x.name===c.name);if(existing){const gain=c.boss?18:c.elite?7:3;prog.echoEssence=(prog.echoEssence||0)+gain;existing.xp+=c.boss?60:c.elite?24:12;notify(`SOMBRA REPETIDA — +${gain} ESSÊNCIA`,1200)}else{const rec=makeEchoRecord(c.name,prog.nextEchoId++,c.elite,!!c.boss);prog.echoes.push(rec);if(c.boss){prog.shadowBossExtractions=(prog.shadowBossExtractions||0)+1;if(!prog.story.firstBossShadow){prog.story.firstBossShadow=true;LevelRuntime.timeout(()=>storyCutscene('A SOMBRA SE CURVA',rec.name+' ergue-se do Vestígio e ajoelha diante de você.','A voz retorna: “Agora você entende. Eles não desaparecem. Eles esperam por um mestre.”'),250)}}if((prog.equippedEchoes||[]).length<echoSlots())prog.equippedEchoes.push(rec.id);notify(c.boss?`SOMBRA DE CHEFE EXTRAÍDA — ${rec.name}`:`SOMBRA EXTRAÍDA — ${rec.name}`,1800)}prog.shadowExtractions=(prog.shadowExtractions||0)+1;c.rise=1;ring(c.x,c.y,'#d7b0ff',190,.75);particle(c.x,c.y,'#8a5cff',34);shadowBurst(c.x,c.y,c.boss?12:7,c.boss?1.5:1);save();if(shadowsSummoned)spawnEchoes()}
