function completeDungeon(){if(currentPortal?.storyMission)return completeStoryMission();sfx('victory');setMusic('hub');camera.target=1;prog.wins++;prog.story=prog.story||clone(defaults.story);prog.story.mainClears=(prog.story.mainClears||0)+1;advanceStory();prog.board=prog.board||clone(defaults.board);prog.board.portals=Math.min(4,(prog.board.portals||0)+1);const repGain=Math.round(({F:3,E:5,D:8,C:12,B:18,A:28,S:50}[currentPortal.rank]||3)*(difficulties[currentDifficulty]?.reward||1));prog.associationRep=(prog.associationRep||0)+repGain;resetDaily();prog.daily.portals=Math.min(2,(prog.daily.portals||0)+1);if(currentPortal.id==='red')prog.redEventCleared=(prog.redEventCleared||0)+1;prog.cleared[currentPortal.id]=(prog.cleared[currentPortal.id]||0)+1;prog.quests.portal.progress=Math.min(prog.quests.portal.goal,(prog.quests.portal.progress||0)+1);const rewardMult=difficulties[currentDifficulty]?.reward||1,rewardXP=Math.round((90+prog.level*12)*rewardMult),rewardGold=Math.round((70+prog.level*12)*rewardMult);if(currentPortal.rank==='S')prog.raidClears=(prog.raidClears||0)+1;awardXP(rewardXP);prog.gold+=rewardGold;const p=currentPortal,name=p.name,rs=window.runStats||{};grantEchoXP(25+(rs.kills||0)*2);save();state='results';modalOpen=true;enemies=[];boss=null;projectiles=[];echoAllies=[];const sec=Math.max(1,Math.round((performance.now()-(rs.start||performance.now()))/1000)),echoes=Math.max(0,prog.echoes.length-(rs.echoStart||0)),score=(rs.kills||0)*40+Math.max(0,500-sec*3)-Math.round((rs.damageTaken||0)*1.5)+echoes*180,grade=score>900?'S':score>700?'A':score>500?'B':'C';UI.resultTitle.textContent=name+' PURIFICADO';UI.resultGrade.textContent=grade;UI.resultBody.innerHTML=`<div><span>Tempo</span><b>${sec}s</b></div><div><span>Abates</span><b>${rs.kills||0}</b></div><div><span>XP da conclusão</span><b>+${rewardXP}</b></div><div><span>Ouro da conclusão</span><b>+${rewardGold}</b></div><div><span>Equipamentos coletados</span><b>${rs.items||0}</b></div><div><span>Novos Ecos</span><b>${echoes}</b></div><div><span>Extração do boss</span><b>${(prog.shadowBossExtractions||0)>(rs.bossShadowStart||0)?'SUCESSO':'NÃO OBTIDA'}</b></div><div><span>Dano sofrido</span><b>${Math.round(rs.damageTaken||0)}</b></div><div><span>Melhor combo</span><b>x${prog.bestCombo||0}</b></div><div><span>Dificuldade</span><b>${difficulties[currentDifficulty]?.name||'VIGILANTE'}</b></div><div><span>Modificador</span><b>${dungeonModifier?.name||'ESTÁVEL'}</b></div><div><span>Salas secretas</span><b>${prog.secretRooms||0}</b></div>`;UI.results.classList.remove('hidden');window.runStats=null}
function usePotion(){if(state==='menu'||modalOpen)return;if((prog.potions||0)<=0){notify('SEM POÇÕES');return}if(player.hp>=player.maxHp){notify('HP JÁ ESTÁ CHEIO');return}prog.potions--;const heal=Math.round(player.maxHp*.45);player.hp=Math.min(player.maxHp,player.hp+heal);particle(player.x,player.y,'#ff6688',20);text(player.x,player.y-40,'+'+heal+' HP','#ff8da7');save()}
function applyDeathPenalty(){const rs=window.runStats||{};const startIds=new Set(rs.inventoryStart||[]),newItems=(prog.inventory||[]).filter(i=>!startIds.has(i.id)),lostItems=newItems.filter((_,i)=>i%2===0);if(lostItems.length){const lost=new Set(lostItems.map(i=>i.id));prog.inventory=prog.inventory.filter(i=>!lost.has(i.id)||Object.values(prog.equipment).includes(i.id))}const gained=Math.max(0,prog.gold-(rs.goldStart||prog.gold)),lostGold=Math.ceil(gained*.35);prog.gold=Math.max(0,prog.gold-lostGold);return {items:lostItems.length,gold:lostGold}}
function damagePlayer(n){if(player.inv>0)return;if(player.blocking&&player.parryT>0){ring(player.x,player.y,'#fff3a6',105,.35);player.inv=.35;player.stamina=Math.min(player.maxStamina,player.stamina+16);notify('PARRY PERFEITO!',700);sfx('parry');camera.kick=12;[...enemies,boss].filter(Boolean).forEach(t=>{if(dist(t,player)<130)hitTarget(t,player.damage*.75,false)});return}let mult=1;if(shadowsSummoned&&shadowCommand==='guard'&&echoAllies.length)mult*=Math.max(.68,1-echoAllies.length*.08);if(player.blocking&&player.stamina>0){mult=.32;player.stamina=Math.max(0,player.stamina-n*.55);if(player.stamina<=0){player.blocking=false;notify('GUARDA QUEBRADA!',900)}}const dmg=Math.max(1,Math.round((n-player.defense*.35)*mult));player.hp-=dmg;if(window.runStats)window.runStats.damageTaken+=dmg;player.inv=player.blocking?.18:.55;shake=player.blocking?3:8;text(player.x,player.y-30,'-'+dmg,player.blocking?'#ffd166':'#ff6b7f');sfx('hurt');camera.kick=Math.max(camera.kick,player.blocking?3:8);if(player.hp<=0){player.hp=0;LevelRuntime.timeout(async()=>{const penalty=applyDeathPenalty();state='hub';SaveManager.persist(save);await releaseCurrentLevel();resetPlayer(true);setMusic('hub');notify(`INCURSÃO FRACASSOU · PERDIDOS ${penalty.items} ITENS / ${penalty.gold} OURO`,2200)},400)}}
function applyStatus(t,type,dur=3,power=1){t.status=t.status||{};t.status[type]=Math.max(t.status[type]||0,dur);t.statusPower=Math.max(t.statusPower||0,power)}
