function renderBuild(){UI.serviceTitle.textContent='BUILD DO CAÇADOR';const a=prog.attributes||defaults.attributes,t=prog.talents||defaults.talents;UI.serviceBody.innerHTML=`<div class="echo-summary"><b class="stat-points">Pontos de Atributo: ${prog.attributePoints||0}</b><span>Pontos de Habilidade: ${prog.skillPoints||0}</span><span>Melhor combo: x${prog.bestCombo||0}</span></div><div class="build-summary">${[['strength','FORÇA','+3 ATQ por ponto'],['vitality','VITALIDADE','+14 HP e defesa'],['agility','AGILIDADE','velocidade e crítico'],['arcane','ARCANO','+7 MP por ponto']].map(x=>`<div class="build-card"><h3>${x[1]} · ${a[x[0]]}</h3><p>${x[2]}</p><button data-stat="${x[0]}" ${(prog.attributePoints||0)<=0?'disabled':''}>+1 PONTO</button></div>`).join('')}</div><div class="skill-tree"><div class="talent ${t.execution?'unlocked':''}"><h3>EXECUÇÃO</h3><p>+22% dano contra inimigos abaixo de 30% HP.</p><button data-talent="execution" ${t.execution?'disabled':''}>${t.execution?'DESBLOQUEADO':'1 PONTO'}</button></div><div class="talent ${t.flow?'unlocked':''}"><h3>FLUXO ARCANO</h3><p>Habilidades consomem 18% menos mana.</p><button data-talent="flow" ${t.flow?'disabled':''}>${t.flow?'DESBLOQUEADO':'1 PONTO'}</button></div><div class="talent ${t.shadow?'unlocked':''}"><h3>PASSO SOMBRIO</h3><p>Dash recarrega mais rápido e aumenta invulnerabilidade.</p><button data-talent="shadow" ${t.shadow?'disabled':''}>${t.shadow?'DESBLOQUEADO':'1 PONTO'}</button></div><div class="service-item"><h3>HABILIDADES EQUIPADAS</h3><p>Escolha a habilidade de cada slot. Gelo aplica lentidão; Inferno aplica queimadura.</p><div class="service-grid">${(prog.skillLoadout||['cut','burst','step']).map((v,i)=>`<label>Slot ${i+1}<select data-skill-slot="${i}"><option value="cut" ${v==='cut'?'selected':''}>Corte da Ruptura</option><option value="burst" ${v==='burst'?'selected':''}>Explosão Arcana</option><option value="step" ${v==='step'?'selected':''}>Passo Fantasma</option><option value="frost" ${v==='frost'?'selected':''}>Prisão Glacial</option><option value="inferno" ${v==='inferno'?'selected':''}>Inferno Abissal</option></select></label>`).join('')}</div></div></div>`;UI.serviceBody.querySelectorAll('[data-skill-slot]').forEach(sel=>sel.onchange=()=>{prog.skillLoadout=prog.skillLoadout||['cut','burst','step'];prog.skillLoadout[+sel.dataset.skillSlot]=sel.value;save();updateUI()});UI.serviceBody.querySelectorAll('[data-stat]').forEach(b=>b.onclick=()=>{if((prog.attributePoints||0)<=0)return;prog.attributePoints--;prog.attributes[b.dataset.stat]++;recalc();save();renderBuild();updateUI()});UI.serviceBody.querySelectorAll('[data-talent]').forEach(b=>b.onclick=()=>{if((prog.skillPoints||0)<=0)return;const k=b.dataset.talent;if(prog.talents[k])return;prog.skillPoints--;prog.talents[k]=true;save();renderBuild();notify('HABILIDADE DESBLOQUEADA')})}
function toggleInventory(force){inventoryOpen=force!==undefined?force:!inventoryOpen;UI.inventory.classList.toggle('hidden',!inventoryOpen);setGamePaused(inventoryOpen);if(inventoryOpen)updateInventory()}
function updateInventory(){recalc();UI.equipWeapon.textContent=equipped('weapon')?.name||'Vazio';UI.equipArmor.textContent=equipped('armor')?.name||'Vazio';UI.equipRing.textContent=equipped('ring')?.name||'Vazio';UI.statAttack.textContent=Math.round(player.damage);UI.statDefense.textContent=Math.round(player.defense);UI.statCrit.textContent=Math.round(player.crit*100)+'%';UI.inventoryGold.textContent=prog.gold;UI.list.innerHTML=prog.inventory.length?prog.inventory.map(i=>`<div class="inventory-item" style="--rarity:${rarities[i.rarity].color}"><div><span class="rarity">${rarities[i.rarity].name} · ${i.slot.toUpperCase()}</span><b>${i.name}</b><small>${i.attack?` ATQ +${i.attack}`:''}${i.defense?` DEF +${i.defense}`:''}${i.hp?` HP +${i.hp}`:''}${i.crit?` CRIT +${Math.round(i.crit*100)}%`:''}</small></div><div class="item-actions"><button data-equip="${i.id}">EQUIPAR</button><button class="ghost" data-sell="${i.id}">VENDER ${i.value}</button></div></div>`).join(''):'<div class="empty-inventory">Nenhum equipamento encontrado.</div>';UI.list.querySelectorAll('[data-equip]').forEach(b=>b.onclick=()=>{const i=prog.inventory.find(x=>x.id==b.dataset.equip);prog.equipment[i.slot]=i.id;recalc();save();updateInventory();updateUI()});UI.list.querySelectorAll('[data-sell]').forEach(b=>b.onclick=()=>{const id=+b.dataset.sell,i=prog.inventory.find(x=>x.id===id);if(!i)return;if(Object.values(prog.equipment).includes(id))return notify('DESEQUIPE O ITEM PRIMEIRO');prog.gold+=i.value;prog.inventory=prog.inventory.filter(x=>x.id!==id);save();updateInventory();updateUI()})}
function updateEchoes(dt){for(const a of [...echoAllies]){const e=a.echo,o=shadowOffsets(a.index),offsetX=o.x,offsetY=o.y;a.x+=(player.x+offsetX-a.x)*dt*6;a.y+=(player.y+offsetY-a.y)*dt*6;a.attackCd-=dt;a.skillCd-=dt;if(a.hp<=0){particle(a.x,a.y,'#6d4a9a',12);echoAllies.splice(echoAllies.indexOf(a),1);continue}const validFocus=shadowFocus&&((shadowFocus===boss&&boss)||enemies.includes(shadowFocus))?shadowFocus:null;const t=validFocus||[...enemies,boss].filter(Boolean).sort((x,y)=>dist(x,a)-dist(y,a))[0];if(!t)continue;let pow=echoPower(e);if(prog.shadowCommander&&activeEchoes().some(x=>x.id==prog.shadowCommander))pow*=1.1;if(shadowCommand==='assault')pow*=1.16;if(shadowCommand==='guard')pow*=.82;const range=e.type==='shooter'?340:235;if(a.skillCd<=0&&dist(t,a)<range){a.skillCd=Math.max(2.2,5.2-e.level*.08)*(shadowCommand==='hunt'?.78:1);if(e.type==='brute'||e.type==='sentinel'){ring(a.x,a.y,echoRanks[e.rarity].color,115,.4);[...enemies,boss].filter(Boolean).forEach(x=>{if(dist(x,a)<115)hitTarget(x,player.damage*.28*pow,false)})}else if(e.type==='wraith'||e.type==='executioner'){hitTarget(t,player.damage*.62*pow,false);particle(t.x,t.y,echoRanks[e.rarity].color,12);a.x=t.x-28;a.y=t.y+18}else{projectiles.push({x:a.x,y:a.y,vx:(t.x-a.x)/(dist(t,a)||1)*330,vy:(t.y-a.y)/(dist(t,a)||1)*330,r:6,d:player.damage*.46*pow,c:echoRanks[e.rarity].color,ally:true})}}else if(a.attackCd<=0&&dist(t,a)<range){a.attackCd=Math.max(.55,1.15-e.level*.015)*(shadowCommand==='hunt'?.76:1);hitTarget(t,player.damage*.25*pow,false);ring(t.x,t.y,echoRanks[e.rarity].color,34,.18)}}}
function update(dt){if(paused||modalOpen||state==='menu'){updateUI();return}if(state!=='menu')time+=dt;legionCd=Math.max(0,legionCd-dt);if(legionTime>0){legionTime=Math.max(0,legionTime-dt);if(legionTime<=0&&echoAllies.some(a=>a.legion)){echoAllies=[];shadowsSummoned=false;notify('LEGIÃO RECOLHIDA',800)}}portalIntro=Math.max(0,portalIntro-dt);camera.kick=Math.max(0,camera.kick-dt*28);camera.zoom+=(camera.target-camera.zoom)*Math.min(1,dt*4);transition=Math.max(0,transition-dt*2.5);shake=Math.max(0,shake-dt*35);player.attackCd=Math.max(0,player.attackCd-dt);player.dashCd=Math.max(0,player.dashCd-dt);player.dashT=Math.max(0,player.dashT-dt);player.inv=Math.max(0,player.inv-dt);player.anim=Math.max(0,player.anim-dt);player.comboT=Math.max(0,player.comboT-dt);player.parryT=Math.max(0,player.parryT-dt);player.blocking=!!keys.KeyC&&player.stamina>0;if(player.blocking)player.stamina=Math.max(0,player.stamina-8*dt);else player.stamina=Math.min(player.maxStamina,player.stamina+24*dt);if(player.comboT<=0)player.combo=0;player.mp=Math.min(player.maxMp,player.mp+10*(dungeonModifier?.mana||1)*dt);player.skillCd=player.skillCd.map(v=>Math.max(0,v-dt));let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0);const m=Math.hypot(dx,dy)||1,s=player.speed*(player.dashT>0?2.8:1);player.x+=dx/m*s*dt;player.y+=dy/m*s*dt;const maxX=state==='hub'?HUB_WIDTH-55:1225;player.x=Math.max(55,Math.min(maxX,player.x));player.y=Math.max(82,Math.min(635,player.y));player.moving=!!(dx||dy); if(dx||dy)player.walk+=dt*12;player.angle=Math.atan2(mouse.y-player.y,mouse.x-player.x);if(state==='hub'){npcs.forEach((n,i)=>{if(n.walker){if(n.baseY==null)n.baseY=n.y;n.x=n.baseX+Math.sin(time*.45+i*1.7)*42;n.y=n.baseY+Math.sin(time*.7+i)*18}});const targetCam=Math.max(0,Math.min(HUB_WIDTH-1280,player.x-640));hubCameraX+=(targetCam-hubCameraX)*Math.min(1,dt*6)}
 if(state==='dungeon'){const r=currentRoom();for(const t of traps){t.cd=Math.max(0,t.cd-dt);if(dist(t,player)<t.r+player.r&&t.cd<=0){t.cd=1.05;damagePlayer(7+prog.level*1.2);ring(t.x,t.y,'#ff536f',t.r+18,.25)}}if(!r?.boss&&enemies.length===0&&wave<roomWaveCount()){waveDelay-=dt;if(waveDelay<=0){spawnWave();waveDelay=.7}}for(const e of [...enemies]){e.hit=Math.max(0,e.hit-dt);e.walk+=dt*5;if(e.status){for(const k of Object.keys(e.status)){e.status[k]-=dt;if(e.status[k]<=0)delete e.status[k]}if(e.status.burn){e.burnTick=(e.burnTick||0)-dt;if(e.burnTick<=0){e.burnTick=.5;hitTarget(e,Math.max(1,player.damage*(e.statusPower||.1)),false)}}if(e.status.bleed){e.bleedTick=(e.bleedTick||0)-dt;if(e.bleedTick<=0){e.bleedTick=.7;hitTarget(e,Math.max(1,player.damage*(e.statusPower||.1)),false)}}}const slow=e.status?.frost?.58:1;const shade=echoAllies.length&&Math.random()<.22?echoAllies.sort((a,b)=>dist(a,e)-dist(b,e))[0]:null,target=shade||player;const d=dist(e,target),a=Math.atan2(target.y-e.y,target.x-e.x);if(e.ranged&&d<420){e.attackCd-=dt;if(e.attackCd<=0){e.attackCd=e.shot||1.25;projectiles.push({x:e.x,y:e.y,vx:Math.cos(a)*250,vy:Math.sin(a)*250,r:7,d:e.d,c:e.c})}if(d>260){e.x+=Math.cos(a)*e.s*slow*dt;e.y+=Math.sin(a)*e.s*slow*dt}}else{e.x+=Math.cos(a)*e.s*slow*dt;e.y+=Math.sin(a)*e.s*slow*dt;if(d<e.r+(target.r||player.r||16)+5&&e.attackCd<=0){e.attackCd=.8;if(target===player)damagePlayer(e.d);else{target.hp-=Math.max(1,e.d*.7);text(target.x,target.y-24,'-'+Math.round(e.d*.7),'#a98cff')}}}e.attackCd=Math.max(0,e.attackCd-dt)}if(boss){boss.hit=Math.max(0,boss.hit-dt);boss.walk+=dt*4;const hpR=boss.hp/boss.maxHp,newPhase=hpR<=.33?3:hpR<=.66?2:1;if(newPhase!==boss.phase){boss.phase=newPhase;boss.s*=1.12;boss.d*=1.1;ring(boss.x,boss.y,boss.color,260,.8);notify(`CHEFE — FASE ${boss.phase}`,1200)}boss.phaseShot-=dt;if(boss.red){boss.teleport-=dt;if(boss.teleport<=0){boss.teleport=Math.max(1.7,3.4-boss.phase*.45);boss.x=720+Math.random()*430;boss.y=150+Math.random()*420;ring(boss.x,boss.y,'#ff5a3c',230,.6);for(let z=0;z<8+boss.phase*2;z++){const aa=z/(8+boss.phase*2)*Math.PI*2;projectiles.push({x:boss.x,y:boss.y,vx:Math.cos(aa)*260,vy:Math.sin(aa)*260,r:9,d:boss.d*.5,c:'#ff7038'})}}}if(boss.celestial){boss.teleport-=dt;if(boss.teleport<=0){boss.teleport=Math.max(1.25,2.8-boss.phase*.35);ring(player.x,player.y,'#fff2a8',145,.45);for(let z=0;z<6+boss.phase*3;z++){const aa=z/(6+boss.phase*3)*Math.PI*2;projectiles.push({x:boss.x,y:boss.y,vx:Math.cos(aa)*310,vy:Math.sin(aa)*310,r:8,d:boss.d*.48,c:'#ffd45f'})}}}const d=dist(boss,player),a=Math.atan2(player.y-boss.y,player.x-boss.x);boss.x+=Math.cos(a)*boss.s*dt;boss.y+=Math.sin(a)*boss.s*dt;boss.slam-=dt;if(d<boss.r+player.r+8)damagePlayer(boss.d*dt*2.5);if(boss.slam<=0){boss.slam=Math.max(1.15,(currentPortal.id==='violet'?1.8:2.5)-boss.phase*.18);ring(boss.x,boss.y,boss.color,180+boss.phase*18,.55);if(d<180+boss.phase*18)damagePlayer(boss.d*.8)}if(boss.phase>=2&&boss.phaseShot<=0){boss.phaseShot=boss.phase===3?1.15:1.8;for(let q=0;q<boss.phase*3;q++){const aa=q/(boss.phase*3)*Math.PI*2;projectiles.push({x:boss.x,y:boss.y,vx:Math.cos(aa)*220,vy:Math.sin(aa)*220,r:8,d:boss.d*.55,c:boss.color})}}}for(const p of [...projectiles]){p.x+=p.vx*dt;p.y+=p.vy*dt;if(!p.ally&&dist(p,player)<p.r+player.r){damagePlayer(p.d);projectiles.splice(projectiles.indexOf(p),1)}else if(p.ally){const t=[...enemies,boss].filter(Boolean).find(t=>dist(p,t)<p.r+t.r);if(t){hitTarget(t,p.d,false);projectiles.splice(projectiles.indexOf(p),1)}}else if(p.x<0||p.x>1280||p.y<0||p.y>720)projectiles.splice(projectiles.indexOf(p),1)}updateEchoes(dt)}
 shadowCorpses.forEach(c=>{if(!c.boss)c.life-=dt});shadowCorpses=shadowCorpses.filter(c=>(c.boss||c.life>0)&&!c.used);deathMarks.forEach(m=>m.life-=dt);deathMarks=deathMarks.filter(m=>m.life>0);ambientMotes.forEach(m=>{m.y-=m.v*dt*18;m.x+=Math.sin(time*.3+m.a)*dt*4;if(m.y<-10)m.y=730});particles.forEach(p=>{p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.94;p.vy*=.94;p.life-=dt});particles=particles.filter(p=>p.life>0);slashes.forEach(s=>s.life-=dt);slashes=slashes.filter(s=>s.life>0);rings.forEach(r=>{r.r+=(r.max-r.r)*dt*9;r.life-=dt});rings=rings.filter(r=>r.life>0);texts.forEach(t=>{t.y-=30*dt;t.life-=dt});texts=texts.filter(t=>t.life>0);shadowFx.forEach(f=>{f.life-=dt;f.y-=dt*45;f.x+=f.drift*dt});shadowFx=shadowFx.filter(f=>f.life>0);updateUI()}
